"use client"
import { AtSign, CircleAlert, CircleCheck, FileCheck, MessageSquare, UserPlus } from "lucide-react"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemMedia,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import type { NotificationItem, NotificationKind } from "../schema"

const ICONS: Record<NotificationKind, React.ReactNode> = {
  mention: <AtSign size={20} aria-hidden />,
  approval: <FileCheck size={20} aria-hidden />,
  payment: <CircleAlert size={20} aria-hidden />,
  comment: <MessageSquare size={20} aria-hidden />,
  deploy: <CircleCheck size={20} aria-hidden />,
  invite: <UserPlus size={20} aria-hidden />,
}

type Props = {
  item: NotificationItem
  onToggleRead: (id: string) => void
  onApprove: (id: string) => void
}

export function NotificationRow({ item, onToggleRead, onApprove }: Props) {
  const unread = !item.read
  return (
    <li
      style={{
        listStyle: "none",
        background: unread ? "var(--atlas-primary-subtle)" : "transparent",
        borderRadius: "var(--atlas-radius-lg)",
      }}
    >
      <ListItem size="md" variant="default">
        <ListItemMedia type="tile" decorative>
          {ICONS[item.kind]}
        </ListItemMedia>
        <ListItemContent>
          <ListItemTitle
            style={{ fontWeight: unread ? "var(--atlas-font-weight-semibold)" : "var(--atlas-font-weight-regular)" }}
          >
            {item.title}
          </ListItemTitle>
          <ListItemDescription>{item.summary}</ListItemDescription>
          <ListItemDescription>
            {item.place} · {item.when}
          </ListItemDescription>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "var(--atlas-spacing-2)",
              marginBlockStart: "var(--atlas-spacing-2)",
            }}
          >
            <Badge size="sm" variant={unread ? "primary" : "neutral"} dot={unread}>
              {unread ? "Unread" : "Read"}
            </Badge>
            {item.kind === "payment" && (
              <Badge size="sm" variant="danger">
                Failed
              </Badge>
            )}
            {item.kind === "approval" &&
              (item.approved ? (
                <Badge size="sm" variant="success">
                  Approved
                </Badge>
              ) : (
                <Button size="sm" variant="primary" onClick={() => onApprove(item.id)}>
                  Approve
                </Button>
              ))}
          </div>
        </ListItemContent>
        <ListItemActions>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => onToggleRead(item.id)}
            aria-label={`Mark “${item.title}” as ${unread ? "read" : "unread"}`}
          >
            {unread ? "Mark read" : "Mark unread"}
          </Button>
        </ListItemActions>
      </ListItem>
    </li>
  )
}

