"use client"
import { useCallback, useEffect, useState } from "react"
import { BellOff, CheckCheck, Inbox } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { EmptyState } from "@atlas/ui-web/compositions/EmptyState/EmptyState"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { TabsList, TabsPanel, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { mockSubmit } from "../../_shared/mockApi"
import { NOTIFICATIONS_SEED, type NotificationItem, type NotificationsView } from "../schema"
import { NotificationRow } from "./NotificationRow"

type Status = "loading" | "ready" | "error"

/** Prototype hook: ?state=loading | empty | error forces that state on first load. */
function forcedState(): string | null {
  if (typeof window === "undefined") return null
  return new URLSearchParams(window.location.search).get("state")
}

const listStyle = {
  display: "flex",
  flexDirection: "column" as const,
  gap: "var(--atlas-spacing-2)",
  margin: 0,
  padding: 0,
}

function LoadingRows() {
  return (
    <div aria-busy="true" aria-label="Loading notifications" style={listStyle}>
      {Array.from({ length: 4 }).map((_, i) => (
        <div key={i} style={{ display: "flex", gap: "var(--atlas-spacing-3)", paddingBlock: "var(--atlas-spacing-3)" }}>
          <Skeleton shape="circle" />
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            <Skeleton style={{ width: "60%" }} />
            <Skeleton />
            <Skeleton style={{ width: "40%" }} />
          </div>
        </div>
      ))}
    </div>
  )
}

export function NotificationList() {
  const [status, setStatus] = useState<Status>("loading")
  const [error, setError] = useState<string | null>(null)
  const [items, setItems] = useState<NotificationItem[]>([])
  const [view, setView] = useState<NotificationsView>("all")
  const [forced, setForced] = useState<string | null>(null)

  useEffect(() => setForced(forcedState()), [])

  const load = useCallback(async (override: string | null) => {
    setStatus("loading")
    setError(null)
    if (override === "loading") return
    try {
      const data = await mockSubmit(override === "empty" ? [] : NOTIFICATIONS_SEED, {
        delayMs: 900,
        failRate: override === "error" ? 1 : 0,
        errorMessage: "We couldn’t reach the server.",
      })
      setItems(data)
      setStatus("ready")
    } catch (e) {
      setError((e as Error).message)
      setStatus("error")
    }
  }, [])

  useEffect(() => {
    load(forced)
  }, [load, forced])

  const unreadCount = items.filter((n) => !n.read).length
  const visible = view === "unread" ? items.filter((n) => !n.read) : items

  const toggleRead = (id: string) =>
    setItems((list) => list.map((n) => (n.id === id ? { ...n, read: !n.read } : n)))
  const approve = (id: string) =>
    setItems((list) => list.map((n) => (n.id === id ? { ...n, approved: true, read: true } : n)))
  const markAllRead = () => setItems((list) => list.map((n) => ({ ...n, read: true })))
  // Retry always fetches for real, so the forced error clears.
  const retry = () => {
    setForced(null)
    if (forced === null) load(null)
  }

  const body = () => {
    if (status === "loading") return <LoadingRows />
    if (status === "error")
      return (
        <Alert
          variant="danger"
          title="Notifications didn’t load"
          description={error ?? "Something went wrong."}
          actions={
            <Button size="sm" variant="outline" onClick={retry}>
              Try again
            </Button>
          }
        />
      )
    if (visible.length === 0)
      return view === "unread" && items.length > 0 ? (
        <EmptyState
          icon={<CheckCheck />}
          title="You’re all caught up"
          description="No unread notifications right now."
          action={
            <Button variant="outline" size="md" onClick={() => setView("all")}>
              View all notifications
            </Button>
          }
        />
      ) : (
        <EmptyState
          icon={items.length === 0 ? <BellOff /> : <Inbox />}
          title="No notifications yet"
          description="When something happens in your projects, it will show up here."
        />
      )
    return (
      <ul style={listStyle} aria-label={view === "unread" ? "Unread notifications" : "All notifications"}>
        {visible.map((item) => (
          <NotificationRow key={item.id} item={item} onToggleRead={toggleRead} onApprove={approve} />
        ))}
      </ul>
    )
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-3)" }}>
        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-text-h1)",
            fontWeight: "var(--atlas-font-weight-bold)",
            lineHeight: "var(--atlas-line-height-tight)",
          }}
        >
          Notifications
        </h1>
        <Button
          size="sm"
          variant="outline"
          leadingIcon={<CheckCheck size={16} aria-hidden />}
          disabled={status !== "ready" || unreadCount === 0}
          onClick={markAllRead}
        >
          Mark all read
        </Button>
      </header>

      <TabsRoot variant="segmented" size="md" value={view} onValueChange={(v) => setView(v as NotificationsView)}>
        <TabsList aria-label="Filter notifications">
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger
            value="unread"
            badge={status === "ready" && unreadCount > 0 ? <Badge size="sm" variant="primary">{unreadCount}</Badge> : undefined}
          >
            Unread
          </TabsTrigger>
        </TabsList>
        <TabsPanel value="all">{view === "all" && body()}</TabsPanel>
        <TabsPanel value="unread">{view === "unread" && body()}</TabsPanel>
      </TabsRoot>
    </div>
  )
}

